// Per-page <head> (meta, Open Graph, JSON-LD), for prerendering (scripts/build.mjs) and navigation.
// Tags needing an absolute URL are only emitted with SITE_URL (brand.json).

import { BRAND_NAME, SITE_URL } from "../brand";
import { LANGS, localize, seoText, type RouteMeta } from "./routes";

const ORG = {
  name: "Beater Studios",
  url: "https://beaterstudios.com/",
  email: "studiosbeater@gmail.com",
  sameAs: ["https://ko-fi.com/beaterstudios"],
};

const HTML_LANG = { pt: "pt-BR", en: "en" } as const;
const OG_LOCALE = { pt: "pt_BR", en: "en_US" } as const;
/** Generated by scripts/gen-images.mjs. */
export const OG_IMAGE = { width: 1200, height: 630, file: (lang: "pt" | "en") => `/og-${lang}.png` };

const esc = (text: string) => text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const abs = (path: string) => `${SITE_URL}${path}`;

export function htmlLang(meta: RouteMeta): string {
  return HTML_LANG[meta.lang];
}

function jsonLd(meta: RouteMeta): object[] {
  const orgId = `${ORG.url}#organization`;
  const out: object[] = [];
  if (meta.id === "home") {
    out.push(
      {
        "@context": "https://schema.org", "@type": "WebSite", name: BRAND_NAME, description: meta.description,
        inLanguage: HTML_LANG[meta.lang], ...(SITE_URL ? { url: abs(localize("/", meta.lang)) } : {}), publisher: { "@id": orgId },
      },
      { "@context": "https://schema.org", "@type": "Organization", "@id": orgId, name: ORG.name, url: ORG.url, email: ORG.email, sameAs: ORG.sameAs },
    );
  }
  if (meta.type === "article") {
    const org = { "@type": "Organization", "@id": orgId, name: ORG.name, url: ORG.url };
    out.push({
      "@context": "https://schema.org", "@type": "TechArticle", headline: meta.name, description: meta.description,
      inLanguage: HTML_LANG[meta.lang], author: org, publisher: org, isPartOf: { "@type": "WebSite", name: BRAND_NAME },
      ...(SITE_URL ? { url: abs(localize(meta.path, meta.lang)), image: abs(OG_IMAGE.file(meta.lang)) } : {}),
    });
  }
  if (meta.breadcrumb && SITE_URL) {
    out.push({
      "@context": "https://schema.org", "@type": "BreadcrumbList",
      itemListElement: meta.breadcrumb.map((c, i) => ({ "@type": "ListItem", position: i + 1, name: c.name, item: abs(localize(c.path, meta.lang)) })),
    });
  }
  return out;
}

export function managedTags(meta: RouteMeta): string {
  const tags: string[] = [`<meta name="description" content="${esc(meta.description)}">`];
  if (meta.noindex) tags.push('<meta name="robots" content="noindex">');
  if (SITE_URL && !meta.noindex) {
    tags.push(`<link rel="canonical" href="${abs(localize(meta.path, meta.lang))}">`);
    for (const lang of LANGS) tags.push(`<link rel="alternate" hreflang="${lang}" href="${abs(localize(meta.path, lang))}">`);
    tags.push(`<link rel="alternate" hreflang="x-default" href="${abs(localize(meta.path, "pt"))}">`);
  }
  const other = meta.lang === "en" ? "pt" : "en";
  tags.push(
    `<meta property="og:type" content="${meta.type}">`,
    `<meta property="og:site_name" content="${esc(BRAND_NAME)}">`,
    `<meta property="og:title" content="${esc(meta.title)}">`,
    `<meta property="og:description" content="${esc(meta.description)}">`,
    `<meta property="og:locale" content="${OG_LOCALE[meta.lang]}">`,
    `<meta property="og:locale:alternate" content="${OG_LOCALE[other]}">`,
  );
  if (SITE_URL) {
    if (!meta.noindex) tags.push(`<meta property="og:url" content="${abs(localize(meta.path, meta.lang))}">`);
    tags.push(
      `<meta property="og:image" content="${abs(OG_IMAGE.file(meta.lang))}">`,
      `<meta property="og:image:width" content="${OG_IMAGE.width}">`,
      `<meta property="og:image:height" content="${OG_IMAGE.height}">`,
      `<meta property="og:image:alt" content="${esc(`${BRAND_NAME}: ${seoText(meta.lang).site.tagline}`)}">`,
      '<meta name="twitter:card" content="summary_large_image">',
    );
  }
  for (const data of jsonLd(meta)) {
    tags.push(`<script type="application/ld+json">${JSON.stringify(data).replace(/</g, "\\u003c")}</script>`);
  }
  return tags.map((tag) => tag.replace(/^<(\w+)/, '<$1 data-head')).join("\n");
}

export function headTags(meta: RouteMeta): string {
  return `<title>${esc(meta.title)}</title>\n${managedTags(meta)}`;
}

export function applyHead(meta: RouteMeta) {
  document.title = meta.title;
  document.head.querySelectorAll("[data-head]").forEach((el) => el.remove());
  document.head.insertAdjacentHTML("beforeend", managedTags(meta));
}
